// Production decision: access token never hits Web Storage
let accessToken: string | null = null;

export const tokenMemory = {
  get: () => accessToken,
  set: (t: string | null) => {
    accessToken = t;
  },
};
// Refresh cookie is Set-Cookie from the API (httpOnly, Secure, SameSite=Lax).

