import { watchDebounced } from "@vueuse/core";

watchDebounced(
  query,
  async (q, _prev, onCleanup) => {
    const ac = new AbortController();
    onCleanup(() => ac.abort());
    results.value = await searchCatalog(q, { signal: ac.signal });
  },
  { debounce: 300 }
);

